    ADMIN_EDITS.meta[id] = { created: Date.now(), modified: Date.now() };
    const leaves = [];
    if (intoLeafId && NODE_BY_ID[intoLeafId] && !nodeIsBranch(NODE_BY_ID[intoLeafId])) { insertChrono(NODE_BY_ID[intoLeafId], id); leaves.push(intoLeafId); }
