    const female = /(female|zira|susan|hazel|jenny|aria|libby|sonia|michelle|natasha|samantha|karen|catherine|emma|ava|joanna|salli|kimberly|ivy|kendra|moira|tessa|fiona|victoria|serena|allison|clara)/i;
